pointLocator.script:
var atual = POA.value;

// Status comunicação
var comunicando = monitor.value;

// Valor atual do acumulador
var diario = self.value;

// Inicialização
if (diario == null || isNaN(diario))
    diario = 0;

// Sem comunicação
if (comunicando != true)
    return diario;

// Valor inválido
if (atual == null || isNaN(atual))
    return diario;

// Proteção negativa
if (atual < 0)
    return diario;

// -------------------------
// DEADBAND NOTURNO
// -------------------------

// Ignora ruído noturno
if (atual < 5)
    return diario;

// Anti salto absurdo
if (atual > 2000)
    return diario;

// -------------------------
// INTEGRAÇÃO TEMPORAL
// -------------------------

// 5 minutos = 5/60 h
var incremento = atual * (5 / 60);

// Soma energia integrada
diario = diario + incremento;

// Limita precisão
diario = Math.round(diario * 1000) / 1000;

return diario;

